{
    static void Main(string[] args)
    {
        try
        {
            var array = new int[] { 1, 2 };
            Console.Write(array[5]);
        }
        catch(ApplicationException e)
        {
            Console.Write(1);
        }
        catch(SystemException e)
        {
            Console.Write(2);
        }
        catch(Exception e)
        {
            Console.Write(3);
        }
        Console.ReadLine();
    }
}
```

Варианты ответов:

- 1

- 2

- 3

- 123

### Вопрос 58

Что будет выведено в результате выполнения программы?

```c#
class Program
{
	private class Test
    {
        public void Print()
        {
            try
            {
                throw new Exception();
            }
            catch (Exception)
            {
                Console.Write("9");
                throw new Exception();
            }
            finally
            {
                Console.Write("2");
            }
        }
    }
    static void Main(string[] args)
    {
        var test = new Test();
        try
        {
            test.Print();
        }
        catch (Exception)
        {
            Console.Write("5");
        }
        finally
        {
            Console.Write("4");
        }
        Console.ReadLine();
    }
}
```

Варианты ответов:

- 92

- 954

- 9254

- Возникнет ошибка на этапе компиляции

